    # link sets it, and a code Smyths does not answer as a product is asked again as a bundle.
    # API default: false.
    # Calls POST /marketplace/smyths-inventory.
    def smyths_inventory(code, bundle: nil)
      post_json("/marketplace/smyths-inventory", {
        mode: "product",
        code: code,
        bundle: bundle,
      })
    end

