    # 'DE'). Leave blank for the country chosen for the site.
    # Calls POST /companies/wellfound.
    def wellfound_company_search(location: nil, industry: nil, url: nil, page: nil, max_results: nil, proxy_country: nil)
      post_json("/companies/wellfound", {
        mode: "search",
